"""Authored anime roster expansion; no VN-only routes or dialogue transcripts.

The factory is supplied by archive_seed so source formatting stays in one place.
Core spoiler-free biographies keep their stable URLs; full journeys are separate.
"""


def build_anime_records(page, text):
    records = []

    def add(slug, category, scope, spoiler, title, summary, body, related, locator, wiki):
        record = page(slug, category, scope, spoiler, title, summary, body, related, locator)
        if wiki:
            record["sources"].append({"title": "Steins;Gate Wiki — secondary reference",
                                      "url": "https://steins-gate.fandom.com/wiki/" + wiki,
                                      "locator": "Anime section; distinguish visual-novel routes. " + locator})
        records.append(record)

    add("amane-suzuha", "character", "shared", 2,
        ("Amane Suzuha · John Titor", "Amane Suzuha · John Titor"),
        ("Lab mem 008; con gái tương lai của Daru và Yuki, với nhiệm vụ khác nhau ở Alpha và Beta.", "Lab member 008; Daru and Yuki's future daughter, with different missions in Alpha and Beta."),
        ("## Danh tính\nSuzuha làm thêm tại tiệm Mr. Braun. Cô là người du hành từ năm 2036 và là con gái của Hashida Itaru cùng Amane Yuki. John Titor là bí danh gắn với hoạt động của cô, không phải một lab mem riêng.\n\n## Alpha\nCô tìm IBN 5100 để chống tương lai do SERN kiểm soát. Máy thời gian gặp hỏng hóc; việc ở lại tìm cha dẫn tới chuyến đi thất bại và mất ký ức. Okabe phải hủy D-mail đã giữ cô ở lại để cô có thể khởi hành đúng lúc.\n\n## Beta và Steins;Gate 0\nMục tiêu chuyển thành ngăn Thế chiến III và cứu Kurisu. Cô tìm Kagari, thúc giục Okabe thử lại và cùng Mayuri thực hiện chuyến đi hỗ trợ quá khứ. Máy thời gian và những gì cô biết khác với bản Alpha; không ghép hai phiên bản thành một người có chung mọi ký ức.",
         "## Identity\nSuzuha works at Mr. Braun's shop. She is a traveler from 2036 and the future daughter of Hashida Itaru and Amane Yuki. John Titor is an associated alias, not an additional lab member.\n\n## Alpha\nShe seeks the IBN 5100 to resist SERN's future. Damage to her machine and the delay while finding her father lead to a failed trip and memory loss. Okabe reverses the D-mail that kept her there so she can depart on time.\n\n## Beta and Steins;Gate 0\nHer mission instead concerns World War III and saving Kurisu. She searches for Kagari, urges Okabe to try again and travels with Mayuri to support the past. Her machine and knowledge differ from Alpha's; the versions do not share every memory."),
        ["hashida-itaru", "amane-yuki", "shiina-kagari", "john-titor", "valkyrie", "sern", "operation-skuld"],
        "Steins;Gate: episodes 14–16, 23–24; Steins;Gate 0: episodes 1, 4–7, 16–23", "Suzuha_Amane")
    add("akiha-rumiho", "character", "shared", 1,
        ("Akiha Rumiho · Faris NyanNyan", "Akiha Rumiho · Faris NyanNyan"),
        ("Lab mem 007; cô chủ MayQueen+Nyan², với D-mail thay đổi số phận cha và diện mạo Akihabara.", "Lab member 007; MayQueen+Nyan²'s proprietor, whose D-mail changes her father's fate and Akihabara."),
        ("## Hồ sơ\nFaris NyanNyan là tên cô dùng ở maid café; tên thật là Akiha Rumiho. Cô chơi RaiNet, quen Daru và Mayuri, và có ảnh hưởng tới văn hóa moe của Akihabara.\n\n## Lựa chọn ở Alpha\nD-mail về một vụ bắt cóc giả khiến cha cô, Yukitaka, tránh chuyến bay định mệnh. Đổi lại, lịch sử Akihabara và đường đi của IBN 5100 thay đổi. Khi Okabe giải thích, cô chấp nhận hủy mong ước ấy dù phải mất cha một lần nữa.\n\n## Trong Steins;Gate 0\nCô vẫn hỗ trợ bạn bè bằng quan hệ, nơi ở và sự chăm sóc dành cho Maho. Không nên gán cho bản anime những kết thúc tình cảm riêng của route Faris trong visual novel.",
         "## Profile\nFaris NyanNyan is her maid-café persona; her name is Akiha Rumiho. A RaiNet player and friend of Daru and Mayuri, she influences Akihabara's moe culture.\n\n## Her Alpha choice\nA false kidnapping D-mail keeps her father Yukitaka off his fatal flight. Akihabara's history and the IBN 5100's whereabouts change as a consequence. After Okabe explains, she accepts reversing her wish despite losing her father again.\n\n## In Steins;Gate 0\nShe supports friends through contacts, accommodation and care for Maho. Her visual-novel route's romantic ending should not be assigned to the anime."),
        ["akiha-yukitaka", "kuroki", "mayqueen-nyan2", "d-mail", "akihabara", "hiyajo-maho"],
        "Steins;Gate: episodes 2, 9, 17; Steins;Gate 0: episodes 5, 9–11", "Faris_NyanNyan")
    add("urushibara-luka", "character", "shared", 2,
        ("Urushibara Luka · Ruka / Lukako", "Urushibara Luka · Ruka / Lukako"),
        ("Lab mem 006; người bạn ở đền Yanabayashi, có D-mail riêng và một vai trò chiến đấu trong tương lai Beta.", "Lab member 006; the friend at Yanabayashi Shrine, with a personal D-mail and a fighting role in Beta's future."),
        ("## Hồ sơ\nLuka, còn được phiên âm Ruka và gọi là Lukako, là con của người trông coi đền Eisuke Urushibara. Luka hiền, rụt rè, thân Mayuri và tin tưởng Okabe.\n\n## Alpha\nD-mail gửi tới mẹ trước khi Luka ra đời làm lịch sử thay đổi; sau đó Luka là nữ ở world line mới. Đây là cơ chế hư cấu, không phải kiến thức sinh học. Luka từng làm hỏng IBN 5100 khi dọn kho. Việc hủy D-mail vì Mayuri đòi hỏi từ bỏ một cuộc đời Luka mong muốn, cùng tình cảm dành cho Okabe.\n\n## Beta\nTrong 0, gia đình ở đền cưu mang Kagari. Đến tương lai chiến tranh năm 2036, Luka tham gia kháng chiến và chiến đấu bảo vệ đồng đội. Đừng lấy sự nhút nhát thời bình làm giới hạn cố định cho nhân vật.",
         "## Profile\nLuka, also romanized Ruka and nicknamed Lukako, is shrine keeper Eisuke Urushibara's child. Gentle and shy, Luka is close to Mayuri and trusts Okabe.\n\n## Alpha\nA D-mail to Luka's mother before birth changes history; Luka is female in the resulting world line. This is fictional mechanics, not biology. Luka had also broken the IBN 5100 while cleaning. Reversing the D-mail for Mayuri means giving up a desired life and confronting feelings for Okabe.\n\n## Beta\nIn 0, the shrine family shelters Kagari. In the war-torn 2036 future, Luka joins the resistance and fights to protect comrades. Peacetime shyness does not define the character's permanent limits."),
        ["urushibara-eisuke", "mayuri-shiina", "shiina-kagari", "d-mail", "valkyrie", "okabe-rintaro"],
        "Steins;Gate: episodes 2, 8, 18; Steins;Gate 0: episodes 5–7, 19–20", "Luka_Urushibara")
    add("kiryu-moeka", "character", "shared", 2,
        ("Kiryu Moeka · Shining Finger", "Kiryu Moeka · Shining Finger"),
        ("Lab mem 005; người tìm IBN 5100 và một Rounder phụ thuộc vào những tin nhắn từ FB.", "Lab member 005; an IBN 5100 seeker and Rounder dependent on messages from FB."),
        ("## Bề ngoài và bí danh\nMoeka ít nói trực tiếp nhưng nhắn điện thoại rất nhanh; Okabe gọi cô là Shining Finger. Cô tìm IBN 5100 và trở thành lab mem 005.\n\n## Alpha\nCô thuộc Rounders và tham gia cuộc đột kích khiến Mayuri chết. D-mail của cô liên quan tới việc đoạt IBN 5100, không phải lời giải thích vô hại cô đưa cho lab. Việc lần theo chỉ thị đưa Okabe tới FB, tức Tennouji Yugo. Trong bản anime, Yugo bắn Moeka rồi tự sát; không thay thế cảnh này bằng tuyến Nae của visual novel.\n\n## Beta\nDaru thuê cô tìm Kagari và cô giúp điều tra. Cùng một gương mặt không có nghĩa mọi hành động ở Alpha đã xảy ra trong Beta; vai trò của cô thay đổi theo hoàn cảnh.",
         "## Appearance and aliases\nMoeka speaks little face to face but types rapidly; Okabe calls her Shining Finger. She seeks the IBN 5100 and becomes lab member 005.\n\n## Alpha\nShe belongs to the Rounders and participates in the raid that kills Mayuri. Her D-mail concerns taking the IBN 5100 rather than the harmless explanation given to the lab. Following her orders leads Okabe to FB, Tennouji Yugo. In the anime Yugo shoots Moeka and then himself; the visual novel's Nae storyline must not replace this scene.\n\n## Beta\nDaru hires her to find Kagari, and she assists the investigation. The same face does not mean Alpha's actions also occurred in Beta; her role changes with circumstances."),
        ["tennouji-yugo", "rounders", "sern", "d-mail", "shiina-kagari", "mayuri-shiina"],
        "Steins;Gate: episodes 6–8, 12–13, 19–20; Steins;Gate 0: episodes 5–7, 13–14", "Moeka_Kiryu")
    add("tennouji-yugo", "character", "shared", 2,
        ("Tennouji Yugo · Mr. Braun / FB", "Tennouji Yugo · Mr. Braun / FB"),
        ("Chủ tiệm TV dưới lab, cha của Nae và người điều phối Rounders dưới bí danh FB.", "The TV-shop owner below the lab, Nae's father and a Rounder handler using the alias FB."),
        ("## Đời sống công khai\nYugo, cũng được viết Yuugo, điều hành Braun Tube Workshop và cho nhóm Okabe thuê tầng trên. Ông nghiêm khắc về tiền thuê và hết sức bảo vệ con gái Nae. Suzuha từng giúp ông khi sống trong quá khứ dưới tên Hashida Suzu.\n\n## Alpha\nFB là bí danh liên lạc của chính Yugo, không phải một phụ nữ khác. Ông điều phối Moeka trong mạng Rounders và bị ràng buộc bởi SERN. Khi bị đối chất ở anime, ông đưa cuộc nói chuyện ra khỏi nhà để tránh Nae, bắn Moeka rồi tự sát.\n\n## Beta\nÔng đánh đuổi kẻ tấn công lab và thỏa thuận bảo vệ nhóm vì Nae cũng có thể bị đe dọa. Không đồng nhất mọi nhóm mặc đồ đen trong 0 với Rounders.",
         "## Public life\nYugo, also spelled Yuugo, runs Braun Tube Workshop and rents the upstairs room to Okabe's group. Strict about rent, he fiercely protects his daughter Nae. Suzuha once helped him while living in the past as Hashida Suzu.\n\n## Alpha\nFB is Yugo's communications alias, not a separate woman. He handles Moeka within the Rounder network and is constrained by SERN. Confronted in the anime, he moves the conversation away from Nae, shoots Moeka and kills himself.\n\n## Beta\nHe repels attackers at the lab and agrees to protect the group because Nae could also be threatened. Not every black-clad group in 0 is the Rounders."),
        ["tennouji-nae", "kiryu-moeka", "amane-suzuha", "rounders", "braun-tube-workshop", "future-gadget-lab"],
        "Steins;Gate: episodes 1–3, 16, 20; Steins;Gate 0: episodes 6–7", "Yuugo_Tennouji")
    add("tennouji-nae", "character", "shared", 1,
        ("Tennouji Nae", "Tennouji Nae"),
        ("Con gái Mr. Braun; sự an toàn của cô ảnh hưởng trực tiếp tới lựa chọn của người cha.", "Mr. Braun's daughter, whose safety directly shapes her father's choices."),
        ("## Hồ sơ\nNae sống cùng Yugo ở dưới phòng lab, thân với Mayuri và xuất hiện trong đời sống hằng ngày của nhóm.\n\n## Vai trò cốt truyện\nQuan hệ cha con giải thích vì sao Yugo muốn tách Nae khỏi công việc nguy hiểm và vì sao ông có thể hợp tác với Okabe để bảo vệ những người ở gần lab.\n\n## Ranh giới bản chuyển thể\nTuyến Nae trưởng thành time leap, trả thù và giết Moeka thuộc visual novel, không phải diễn biến của anime truyền hình. Cũng không tự nhập tiểu sử Nae trong Robotics;Notes vào thời điểm Steins;Gate.",
         "## Profile\nNae lives with Yugo beneath the lab, is close to Mayuri and appears in the group's everyday life.\n\n## Story role\nTheir father-daughter bond explains Yugo's efforts to separate her from dangerous work and his willingness to cooperate with Okabe to protect people around the lab.\n\n## Adaptation boundary\nThe adult Nae time-leap, revenge and Moeka-killing storyline belongs to the visual novel, not the TV anime. Her later Robotics;Notes biography should not automatically be imported into this period either."),
        ["tennouji-yugo", "mayuri-shiina", "braun-tube-workshop", "kiryu-moeka"],
        "Steins;Gate: episodes 2, 12, 20, 24; Steins;Gate 0: episodes 6–7", "Nae_Tennouji")
    add("amane-yuki", "character", "sg0", 2,
        ("Amane Yuki", "Amane Yuki"),
        ("Bạn cosplay của Mayuri, người yêu tương lai của Daru và mẹ của Suzuha.", "Mayuri's cosplay friend, Daru's future partner and Suzuha's mother."),
        ("## Hồ sơ\nYuki thuộc nhóm bạn cosplay của Mayuri. Tính cách cởi mở giúp Daru bớt lúng túng; Suzuha âm thầm muốn hai người đến gần nhau.\n\n## Gia đình và nhân quả\nCô là mẹ tương lai của Suzuha. Những buổi gặp với Daru cho thấy tương lai cần được tạo nên từ các quan hệ đời thường. Cô cũng là một mắt xích khi nhóm tìm nguồn gốc bài hát Kagari nhớ.\n\n## Tránh trộn route\nAnime không sử dụng tuyến Kagari phẫu thuật để giả làm Yuki của một nhánh visual novel. Vết thương hoặc cảnh gợi nghi ngờ không đủ để kết luận Yuki trong anime là người giả.",
         "## Profile\nYuki belongs to Mayuri's cosplay circle. Her openness helps Daru feel less awkward, while Suzuha quietly hopes to bring them together.\n\n## Family and causality\nShe is Suzuha's future mother. Her meetings with Daru show a future being built through ordinary relationships. She is also a link in the search for the song Kagari remembers.\n\n## Avoid mixing routes\nThe anime does not adopt the visual-novel branch where Kagari undergoes surgery to impersonate Yuki. Injuries and suspicious framing do not establish that the anime's Yuki is an impostor."),
        ["hashida-itaru", "amane-suzuha", "mayuri-shiina", "shiina-kagari", "okabe-mother"],
        "Steins;Gate 0: episodes 3, 12, 15; compare VN-only impersonation separately", "Yuki_Amane")
    add("shiina-kagari", "character", "sg0", 2,
        ("Shiina Kagari", "Shiina Kagari"),
        ("Con nuôi của Mayuri từ tương lai chiến tranh; mất tích, ký ức và thao túng nối cô với cuộc tranh giành công nghệ.", "Mayuri's adopted daughter from the wartime future; disappearance, memory and manipulation connect her to the technology race."),
        ("## Danh tính\nKagari là trẻ mồ côi chiến tranh được Mayuri nhận nuôi trong tương lai. Cô đi về quá khứ với Suzuha, bị lạc trong năm 1998, rồi xuất hiện ở hiện tại khi đã lớn và mất trí nhớ. Gia đình Luka cưu mang cô.\n\n## Ký ức và hành động\nSự gần gũi với Mayuri cùng bài hát giúp khơi lại liên hệ gia đình. Leskinen lợi dụng việc điều kiện hóa tâm lý để biến cô thành công cụ; tình cảm dành cho Mayuri đối chọi với sự thao túng đó. Cô tham gia các biến cố quanh chuyến đi của Mayuri và Suzuha.\n\n## Phân biệt\nNgoại hình giống Kurisu không chứng minh cô là bản sao sinh học, con của Kurisu hoặc Amadeus nhập vào người. Không tự nhập việc thay ký ức bằng Kurisu hay giả Yuki từ các route VN vào anime.",
         "## Identity\nKagari is a war orphan adopted by Mayuri in the future. Traveling into the past with Suzuha, she becomes separated in 1998 and later appears as an adult with amnesia. Luka's family shelters her.\n\n## Memory and action\nCloseness to Mayuri and a song help revive her family connection. Leskinen exploits psychological conditioning to use her as a tool; her attachment to Mayuri conflicts with that manipulation. She becomes involved in the events surrounding Mayuri and Suzuha's departure.\n\n## Distinctions\nResembling Kurisu does not establish that she is a biological clone, Kurisu's daughter or an embodied Amadeus. Kurisu-memory replacement and Yuki impersonation from VN routes must not automatically be assigned to the anime."),
        ["mayuri-shiina", "amane-suzuha", "alexis-leskinen", "urushibara-luka", "urushibara-eisuke", "amane-yuki"],
        "Steins;Gate 0: episodes 4–7, 12–13, 17–18, 21–23", "Kagari_Shiina")
    add("alexis-leskinen", "character", "sg0", 2,
        ("Alexis Leskinen", "Alexis Leskinen"),
        ("Giáo sư phụ trách nghiên cứu Amadeus; vỏ bọc học thuật che hoạt động cho Strategic Focus.", "The professor overseeing Amadeus research, whose academic role covers work for Strategic Focus."),
        ("## Vai trò công khai\nLeskinen là giáo sư tại Viktor Chondria, thuộc môi trường nghiên cứu khoa học thần kinh của Kurisu và Maho. Ông giới thiệu Amadeus và đưa Okabe vào chương trình thử nghiệm.\n\n## Bí mật trong anime 0\nÔng phục vụ Strategic Focus, còn được gọi Stratfo hoặc Stratfor tùy bản dịch, và tìm cách chiếm nghiên cứu du hành thời gian. Kagari bị lợi dụng để chuyển thông tin và thực hiện hành động theo sự điều kiện hóa. Các lần can thiệp ở Radio Kaikan làm lộ sự đối đầu giữa mục tiêu của ông và nhóm lab.\n\n## Đối trọng\nReyes không đơn giản là cấp dưới cùng phe; bà có liên hệ với DURPA. Maho tham gia nghiên cứu không đồng nghĩa cô biết hoặc đồng ý với âm mưu của thầy.",
         "## Public role\nLeskinen is a Viktor Chondria professor in Kurisu and Maho's neuroscience research environment. He introduces Amadeus and recruits Okabe as a tester.\n\n## Secret role in anime 0\nHe serves Strategic Focus, also rendered Stratfo or Stratfor, and seeks time-travel research. Kagari is exploited to carry information and act under conditioning. His interventions at Radio Kaikan expose the conflict between his objectives and the lab.\n\n## Opposing interests\nReyes is not simply a subordinate on the same side; she has DURPA ties. Maho's research participation does not imply knowledge of, or consent to, her mentor's conspiracy."),
        ["hiyajo-maho", "judy-reyes", "shiina-kagari", "strategic-focus", "viktor-chondria", "amadeus"],
        "Steins;Gate 0: episodes 1–3, 17–18, 21–23", "Alexis_Leskinen")
    add("judy-reyes", "character", "sg0", 2,
        ("Judy Reyes", "Judy Reyes"),
        ("Giáo sư tâm sinh lý tại Viktor Chondria và người hoạt động cho DURPA trong cuộc đua nghiên cứu.", "A Viktor Chondria psychophysiology professor working for DURPA in the research race."),
        ("## Hồ sơ\nReyes quen Leskinen và Maho trong môi trường học thuật tại Viktor Chondria. Vẻ ngoài thân thiện không nói lên toàn bộ mục tiêu của bà.\n\n## Anime 0\nBà có liên hệ với DURPA, một phe cạnh tranh với Strategic Focus. Danh tính kẻ tấn công mặc đồ mô tô gắn với bà được phân biệt với các nghi ngờ hướng về Yuki. Các biến cố trên sân thượng Radio Kaikan cho thấy hai phe không phải một đội thống nhất.\n\n## Ranh giới\nVai trò và kết cục thay đổi giữa world line và route. Không lấy cảnh Reyes thay ký ức Kagari trong một nhánh VN làm sự kiện đã xảy ra trong bản anime.",
         "## Profile\nReyes knows Leskinen and Maho through Viktor Chondria's academic environment. A friendly appearance does not reveal her entire agenda.\n\n## Anime 0\nShe has DURPA ties, placing her with a rival to Strategic Focus. Her connection to the motorcycle-suited attacker must be distinguished from suspicion directed at Yuki. The Radio Kaikan rooftop events show that the factions are not one unified team.\n\n## Boundaries\nHer role and outcome vary by world line and route. The VN branch in which Reyes overwrites Kagari's memories must not be treated as an event already shown in the anime."),
        ["durpa", "alexis-leskinen", "hiyajo-maho", "shiina-kagari", "amane-yuki", "viktor-chondria"],
        "Steins;Gate 0: episodes 5, 7, 10–11, 17–18, 21–23", "Judy_Reyes")
    add("nakase-katsumi", "character", "sg0", 2,
        ("Nakase Katsumi · Fubuki", "Nakase Katsumi · Fubuki"),
        ("Bạn cosplay của Mayuri; những ký ức bất thường mở rộng câu hỏi về tàn dư world line.", "Mayuri's cosplay friend, whose unusual memories broaden the question of world-line remnants."),
        ("## Tên và quan hệ\nTên thật là Nakase Katsumi; Fubuki là tên cosplay, không phải tên của một người khác. Cô thường xuất hiện cùng Kaede trong nhóm bạn Mayuri.\n\n## Vai trò\nNhững trải nghiệm giống ký ức từ hoàn cảnh khác và việc cô phải đến bệnh viện khiến Okabe nhận ra các tàn dư ký ức không chỉ có một hình thức. Điều đó không chứng minh Fubuki kiểm soát world line hay có Reading Steiner giống hệt Okabe. Cô cũng xuất hiện trong nhóm sống sót ở tương lai chiến tranh.\n\n## Phạm vi\nKhông thêm các tuyến của người thân hoặc tác phẩm phụ chưa được anime triển khai chỉ vì chúng xuất hiện trong tiểu sử tổng hợp.",
         "## Name and relationships\nHer name is Nakase Katsumi; Fubuki is her cosplay name, not another person. She commonly appears with Kaede in Mayuri's circle.\n\n## Role\nExperiences resembling memories from different circumstances and her hospitalization alert Okabe to more than one form of memory remnants. They do not prove that Fubuki controls world lines or has an identical Reading Steiner ability. She also appears among the wartime future's survivors.\n\n## Scope\nRelatives' storylines and side works absent from the anime should not be added simply because a franchise-wide biography lists them."),
        ["kurushima-kaede", "mayuri-shiina", "reading-steiner", "valkyrie"],
        "Steins;Gate 0: episodes 3–4, 9–10, 19–20", "Katsumi_Nakase")
    add("kurushima-kaede", "character", "sg0", 2,
        ("Kurushima Kaede", "Kurushima Kaede"),
        ("Bạn cosplay của Mayuri và Fubuki, nối đời thường của nhóm với những người sống sót trong tương lai.", "Mayuri and Fubuki's cosplay friend, connecting the group's everyday circle with future survivors."),
        ("## Hồ sơ\nKaede là bạn trong nhóm cosplay của Mayuri, thường đi cùng Fubuki và quen Yuki. Cô giúp phần đời sống của lab có một mạng bạn bè rộng hơn nhóm làm kỹ thuật.\n\n## Vai trò trong 0\nCô hiện diện trong những cuộc gặp, chăm sóc và hỗ trợ bạn bè; về sau xuất hiện trong bối cảnh kháng chiến năm 2036. Đây là nhân vật hỗ trợ có tính liên tục, không phải người phát minh Amadeus hay một lãnh đạo tình báo bí mật.\n\n## Phân biệt\nKaede và Nakase Katsumi là hai người riêng. Fubuki là bí danh của Katsumi, không phải của Kaede.",
         "## Profile\nKaede is part of Mayuri's cosplay circle, frequently accompanies Fubuki and knows Yuki. She gives the lab's everyday life a wider social network beyond its technical members.\n\n## Role in 0\nShe appears in gatherings and support for friends, and later in the 2036 resistance setting. She is a continuing supporting character, not an Amadeus inventor or secret intelligence chief.\n\n## Distinction\nKaede and Nakase Katsumi are separate people. Fubuki is Katsumi's alias, not Kaede's."),
        ["nakase-katsumi", "mayuri-shiina", "amane-yuki", "valkyrie"],
        "Steins;Gate 0: episodes 3, 6, 15, 19–20", "Kaede_Kurushima")
    add("doctor-nakabachi", "character", "shared", 1,
        ("Doctor Nakabachi · cha của Kurisu", "Doctor Nakabachi · Kurisu's father"),
        ("Người diễn thuyết ở Radio Kaikan; sự ghen tị và việc chiếm luận văn của Kurisu dẫn tới cuộc đua thời gian.", "The Radio Kaikan lecturer whose jealousy and theft of Kurisu's thesis drive the time-travel race."),
        ("## Danh tính và xung đột\nDoctor Nakabachi là cha của Kurisu. Quan hệ cha con đã rạn nứt vì ông không chịu nổi việc năng lực của con vượt mình. Bài thuyết trình của ông ở Radio Kaikan liên quan tới những tuyên bố về du hành thời gian của John Titor.\n\n## Beta\nCuộc đối đầu với Kurisu dẫn tới tình huống Okabe vô tình đâm cô trong lần cứu đầu. Nakabachi lấy luận văn và đem sang Nga, mở đường cho cuộc tranh giành nghiên cứu dẫn tới Thế chiến III.\n\n## Operation Skuld\nCứu Kurisu vẫn chưa đủ: kế hoạch còn phải khiến luận văn không sống sót trên đường tới Nga. Tên thật trong tài liệu mở rộng không cần được suy đoán từ cách xưng hô của anime.",
         "## Identity and conflict\nDoctor Nakabachi is Kurisu's father. Their relationship has broken down because he cannot accept being surpassed by his daughter. His Radio Kaikan lecture involves John Titor's time-travel claims.\n\n## Beta\nThe confrontation with Kurisu leads to Okabe accidentally stabbing her in his first rescue attempt. Nakabachi steals her thesis and takes it toward Russia, enabling the research race leading to World War III.\n\n## Operation Skuld\nSaving Kurisu alone is insufficient: the thesis must also fail to survive its journey to Russia. A personal name found in supplementary material need not be inferred from the anime's forms of address."),
        ["makise-kurisu", "radio-kaikan", "john-titor", "russian-time-program", "operation-skuld", "beta-field"],
        "Steins;Gate: episodes 1, 23–24; Steins;Gate 0: background premise", "Dr._Nakabachi")
    add("akiha-yukitaka", "character", "sg", 1,
        ("Akiha Yukitaka · cha của Faris", "Akiha Yukitaka · Faris's father"),
        ("Cha của Rumiho; cái chết, lần được cứu và liên hệ IBN 5100 làm nên lựa chọn của Faris.", "Rumiho's father; his death, rescue and IBN 5100 connection shape Faris's choice."),
        ("## Gia đình\nYukitaka là cha của Akiha Rumiho. Việc ông qua đời trong tai nạn máy bay là mất mát khiến Faris muốn gửi D-mail.\n\n## Chuỗi hệ quả\nTin về một vụ bắt cóc giả giữ ông ở lại. Ông sống sót, nhưng lựa chọn bán IBN 5100 để có tiền cứu con thay đổi nơi chiếc máy đáng lẽ xuất hiện. Lịch sử văn hóa Akihabara cũng khác. Ông có liên hệ với Suzuha sống trong quá khứ dưới tên Hashida Suzu.\n\n## Ý nghĩa\nHủy D-mail không phải hoàn tác một món đồ đơn thuần: Faris biết mình sẽ từ bỏ cuộc sống còn cha. Những tuyến quan hệ mở rộng ngoài anime không được tự thêm vào hồ sơ này.",
         "## Family\nYukitaka is Akiha Rumiho's father. His death in a plane crash motivates Faris to send a D-mail.\n\n## Consequences\nA false kidnapping message keeps him from leaving. He survives, but selling the IBN 5100 to fund his daughter's rescue changes the computer's whereabouts. Akihabara's cultural history also differs. He is connected to Suzuha's past life as Hashida Suzu.\n\n## Significance\nReversing the D-mail is not merely restoring an object: Faris knowingly gives up life with her father. Expanded relationships from outside the anime are not automatically added here."),
        ["akiha-rumiho", "amane-suzuha", "kuroki", "d-mail", "akihabara"],
        "Steins;Gate: episodes 9, 16–17", "Yukitaka_Akiha")
    add("urushibara-eisuke", "character", "shared", 2,
        ("Urushibara Eisuke", "Urushibara Eisuke"),
        ("Cha của Luka và người coi sóc đền Yanabayashi; nối tuyến IBN 5100 với việc cưu mang Kagari.", "Luka's father and Yanabayashi Shrine's keeper, linking the IBN 5100 setting with Kagari's shelter."),
        ("## Hồ sơ\nEisuke là cha của Luka, gắn với đền Yanabayashi nơi nhóm tìm thấy IBN 5100 ở một số lịch sử.\n\n## Vai trò hỗ trợ\nSự hiện diện của ông đặt Luka trong bối cảnh gia đình và nơi thờ tự, thay vì chỉ là một thành viên lab. Trong 0, gia đình ông nhận chăm sóc cô gái mất trí nhớ về sau được nhận ra là Kagari.\n\n## Giới hạn\nCưu mang Kagari không có nghĩa ông biết trước nguồn gốc tương lai hay tham gia thí nghiệm của Leskinen. Anime không cung cấp cơ sở để gán cho ông một vai trò tình báo.",
         "## Profile\nEisuke is Luka's father and is associated with Yanabayashi Shrine, where the group finds the IBN 5100 in some histories.\n\n## Supporting role\nHe places Luka within a family and shrine setting rather than only a lab membership. In 0, his family cares for the amnesiac girl later identified as Kagari.\n\n## Limits\nSheltering Kagari does not mean he knew her future origin or participated in Leskinen's experiments. The anime gives no basis for assigning him an intelligence role."),
        ["urushibara-luka", "shiina-kagari", "amane-suzuha", "akiha-yukitaka"],
        "Steins;Gate: episodes 2–3, 17–18; Steins;Gate 0: episodes 5–7", "Eisuke_Urushibara")
    add("kuroki", "character", "sg", 1,
        ("Kuroki · quản gia nhà Akiha", "Kuroki · the Akiha family's butler"),
        ("Nhân vật hỗ trợ trong tuyến gia đình Faris; phạm vi xuất hiện ở anime rất ngắn.", "A supporting figure in Faris's family storyline, with a very brief anime appearance."),
        ("## Vai trò\nKuroki là người phục vụ, quản gia gắn với gia đình Akiha. Hồ sơ được giữ vì ông thuộc nhóm nhân vật có tên trong tuyến Faris, dù anime dành rất ít thời lượng.\n\n## Phạm vi anime\nĐối chiếu phần gia đình Rumiho ở tập 17. Không lấy thiết kế nhân vật, năng lực chiến đấu hoặc những cảnh dài hơn ở Linear Bounded Phenogram và manga làm cảnh đã xuất hiện trong anime.\n\n## Liên hệ\nQuan hệ quan trọng ở đây là với Rumiho và cha cô, Yukitaka; không có căn cứ để biến ông thành thành viên Rounders.",
         "## Role\nKuroki is the servant or butler associated with the Akiha household. He is retained as a named figure in Faris's storyline despite receiving very little anime time.\n\n## Anime scope\nConsult Rumiho's family sequence in episode 17. Character designs, combat abilities and longer scenes from Linear Bounded Phenogram or manga are not automatically anime scenes.\n\n## Connections\nHis relevant relationships are with Rumiho and her father Yukitaka; there is no basis here to make him a Rounder."),
        ["akiha-rumiho", "akiha-yukitaka"], "Steins;Gate: episode 17; brief supporting credit", "Kuroki")
    add("shido-4c", "character", "sg", 1,
        ("4℃ · Shido", "4℃ · Shido"),
        ("Đối thủ gắn với nhóm Viral Attackers trong tuyến Faris; anime chỉ cho nghe giọng ở tập 17.", "An opponent associated with the Viral Attackers in Faris's storyline; heard only in anime episode 17."),
        ("## Hồ sơ\n4℃ được đọc là Shido. Nhân vật thuộc tuyến đối thủ RaiNet và nhóm Viral Attackers gắn với Faris.\n\n## Vai trò trong anime\nTập 17 chỉ có phần giọng nói, không chuyển thể đầy đủ các cảnh đối đầu trong chương Faris của visual novel. Vì vậy, hồ sơ không mô tả toàn bộ cuộc đánh đuổi hoặc kết quả thi đấu VN như cảnh anime.\n\n## Phân biệt\nĐây là đối thủ cục bộ trong tuyến nhân vật, không phải lãnh đạo SERN, tổ chức tình báo hay người du hành thời gian.",
         "## Profile\n4℃ is read as Shido. He belongs to the RaiNet-opponent and Viral Attackers strand associated with Faris.\n\n## Anime role\nEpisode 17 includes his voice only and does not adapt the full confrontations from the visual novel's Faris chapter. The complete VN pursuit and competition results are therefore not presented here as anime scenes.\n\n## Distinction\nHe is a local antagonist in a character strand, not a SERN leader, intelligence organization or time traveler."),
        ["akiha-rumiho", "viral-attackers"], "Steins;Gate: episode 17, voice only", "4%E2%84%83")
    add("mayuri-grandmother", "character", "sg", 1,
        ("Bà của Mayuri · không nêu tên", "Mayuri's grandmother · unnamed"),
        ("Người thân trong hồi tưởng; mất mát của Mayuri là một nền tảng của quan hệ với Okabe.", "A relative seen through recollection; Mayuri's bereavement underlies her bond with Okabe."),
        ("## Thân phận\nAnime không nêu tên riêng của bà. Đây là một hồ sơ người thân không có tên, không phải một nhân vật mang họ tên do dự án tự đặt.\n\n## Ảnh hưởng cốt truyện\nSau khi bà qua đời, Mayuri thường tới mộ và chìm trong buồn bã. Okabe kéo bạn trở lại đời sống bằng vai diễn nhà khoa học điên và cách gọi cô là con tin. Những lần Mayuri nói chuyện tại mộ nối sự ấm áp hiện tại với nỗi đau đã có từ trước các thí nghiệm.\n\n## Giới hạn\nKhông suy ra nguyên nhân qua đời, ngày tháng hoặc một năng lực siêu nhiên mà anime không xác nhận.",
         "## Identity\nThe anime gives her no personal name. This is an unnamed-relative record, not a new name invented by the project.\n\n## Story impact\nAfter her death Mayuri repeatedly visits her grave and withdraws into grief. Okabe draws his friend back into life through his mad-scientist performance and his claim that she is his hostage. Mayuri's later graveside conversations connect her present warmth with loss predating the experiments.\n\n## Limits\nNo cause of death, dates or supernatural ability absent from the anime is inferred."),
        ["mayuri-shiina", "okabe-rintaro", "mayuri-journey"], "Steins;Gate: episodes 13, 21", "Mayuri_Shiina/Relationships")
    add("okabe-mother", "character", "sg0", 2,
        ("Mẹ của Okabe · không nêu tên", "Okabe's mother · unnamed"),
        ("Người thân xuất hiện qua liên lạc, là mắt xích trong quá trình truy nguồn bài hát Kagari nhớ.", "A relative heard through communication, linking the search for the song Kagari remembers."),
        ("## Thân phận\nAnime không cung cấp tên riêng cho mẹ Okabe trong tuyến này. Không gán cho bà một tên hoặc chức vụ không có trong tác phẩm.\n\n## Vai trò ở tập 12\nKhi truy nguồn bài hát gắn với Kagari, nhóm lần tới Yuki và mẹ Okabe; bà nhớ từng nghe Okabe hát lúc nhỏ. Chi tiết này tạo một vòng nối giữa ký ức tuổi thơ và thông tin đi qua các thời điểm.\n\n## Giới hạn\nBà không được xác lập là người sáng tác bài hát hoặc một người du hành thời gian. Một mắt xích truyền lại thông tin không đồng nghĩa nguồn gốc đầu tiên của nó đã được chứng minh.",
         "## Identity\nThe anime does not provide Okabe's mother's personal name in this strand. No unsupported name or occupation is assigned.\n\n## Episode 12 role\nTracing the song associated with Kagari leads the group through Yuki to Okabe's mother, who remembers hearing him sing as a child. This connects childhood memory with information passed between different times.\n\n## Limits\nShe is not established as the song's composer or a time traveler. Being a transmission link does not prove the information's original source."),
        ["okabe-rintaro", "amane-yuki", "shiina-kagari", "mayuri-shiina"], "Steins;Gate 0: episode 12", "Kagari_Shiina/Plot")

    # Institutions, factions and story-relevant businesses are distinguished in text.
    add("rounders", "organization", "shared", 2,
        ("Rounders", "Rounders"),
        ("Mạng đặc vụ thực địa phục vụ lợi ích SERN; FB điều phối nhóm có Moeka ở Akihabara.", "A field-operative network serving SERN's interests; FB handles Moeka's Akihabara group."),
        ("## Loại tổ chức\nRounders là mạng tác chiến và thu thập mục tiêu, có liên hệ hoạt động với SERN; không phải tên khác của một phòng thí nghiệm khoa học.\n\n## Nhân sự và hành động\nMoeka là thành viên; Yugo sử dụng bí danh FB để chỉ đạo. Ở Alpha, việc lấy IBN 5100 và đột kích Future Gadget Lab khiến nhóm trở thành mối đe dọa trực tiếp.\n\n## Beta\nTrong anime 0, Yugo có thể thỏa thuận giúp Okabe; điều đó không làm mọi Rounder trở thành bạn vĩnh viễn. Strategic Focus và DURPA là các phe khác, dù có những đội tấn công ăn mặc tương tự.",
         "## Organization type\nThe Rounders are an operational network obtaining targets and serving SERN-linked interests, not another name for a scientific laboratory.\n\n## Personnel and actions\nMoeka is a member; Yugo directs her as FB. In Alpha their pursuit of the IBN 5100 and raid on Future Gadget Lab make them an immediate threat.\n\n## Beta\nYugo can strike a deal with Okabe in anime 0; this does not make every Rounder a permanent friend. Strategic Focus and DURPA are different factions despite similarly dressed attack teams."),
        ["sern", "kiryu-moeka", "tennouji-yugo", "future-gadget-lab", "strategic-focus", "durpa"],
        "Steins;Gate: episodes 12–13, 19–20; Steins;Gate 0: episodes 5–7, 21–23", "Rounders")
    add("valkyrie", "organization", "shared", 2,
        ("Valkyrie · lực lượng kháng chiến", "Valkyrie · the resistance"),
        ("Tên lực lượng kháng chiến gắn với nhóm lab trong tương lai; đối thủ và hoàn cảnh khác giữa Alpha, Beta.", "The resistance associated with the lab's future, with different enemies and circumstances in Alpha and Beta."),
        ("## Alpha\nSuzuha mô tả một tương lai bị SERN kiểm soát và những người chống lại trật tự đó. Okabe cùng Daru gắn với nền tảng kháng chiến.\n\n## Beta trong anime 0\nTrong tương lai chiến tranh, Daru, Maho và các đồng đội duy trì căn cứ, kỹ thuật time leap và hy vọng thay đổi lịch sử. Luka chiến đấu bảo vệ nhóm; Fubuki và Kaede hiện diện trong mạng sống sót. Okabe trở lại hành động sau khi chứng kiến tương lai này.\n\n## Không đồng nhất\nValkyrie không phải tên chính thức của Future Gadget Lab từ lúc thành lập, cũng không phải một quân đội ngoài đời. Thành viên, đối thủ và nguồn lực phải đọc theo đúng world line.",
         "## Alpha\nSuzuha describes a SERN-controlled future and resistance against it. Okabe and Daru are associated with that resistance's foundations.\n\n## Beta in anime 0\nIn the wartime future, Daru, Maho and their allies maintain a base, time-leap technology and hope of changing history. Luka fights to protect them; Fubuki and Kaede are part of the surviving circle. Witnessing this future helps bring Okabe back into action.\n\n## Distinctions\nValkyrie is not Future Gadget Lab's official name from its inception and is not a real-world army. Membership, opponents and resources depend on the world line."),
        ["future-gadget-lab", "amane-suzuha", "hashida-itaru", "hiyajo-maho", "urushibara-luka", "nakase-katsumi", "kurushima-kaede", "alpha-field", "beta-field"],
        "Steins;Gate: episodes 14–16; Steins;Gate 0: episodes 19–23", "Valkyrie")
    add("strategic-focus", "organization", "sg0", 2,
        ("Strategic Focus · Stratfo / Stratfor", "Strategic Focus · Stratfo / Stratfor"),
        ("Phe tình báo hư cấu gắn với Leskinen, nhắm tới Amadeus và nghiên cứu du hành thời gian.", "The fictional intelligence faction linked to Leskinen, targeting Amadeus and time-travel research."),
        ("## Tên gọi\nStrategic Focus xuất hiện dưới các cách ghi Stratfo, Stratfor hoặc cách rút gọn khác tùy bản dịch. Hồ sơ này nói về phe trong tác phẩm, không đưa ra cáo buộc về một doanh nghiệp ngoài đời.\n\n## Người và mục tiêu\nLeskinen là nhân sự liên quan trực tiếp. Amadeus, tri thức của Kurisu và máy thời gian là những mục tiêu có thể tạo ưu thế cho phe này. Kagari bị thao túng trong chuỗi kế hoạch.\n\n## Đối đầu\nDURPA và các lực lượng Nga cạnh tranh vì công nghệ; Rounders là mạng khác. Viktor Chondria là nơi làm nghiên cứu, không có nghĩa toàn bộ trường là một chi nhánh tình báo.",
         "## Names\nStrategic Focus is rendered Stratfo, Stratfor or another abbreviated spelling across translations. This record concerns the fictional faction, not allegations about a real company.\n\n## Personnel and objectives\nLeskinen is directly associated with it. Amadeus, Kurisu's knowledge and time machines offer possible advantages; Kagari is manipulated within the plans.\n\n## Conflict\nDURPA and Russian forces compete for technology, while the Rounders are a separate network. Viktor Chondria is a research setting; the entire university is not thereby an intelligence branch."),
        ["alexis-leskinen", "shiina-kagari", "amadeus", "viktor-chondria", "durpa", "russian-time-program"],
        "Steins;Gate 0: episodes 17–18, 21–23", "Strategic_Focus")
    add("durpa", "organization", "sg0", 2,
        ("DURPA", "DURPA"),
        ("Cơ quan nghiên cứu quốc phòng hư cấu, gắn với Judy Reyes và cạnh tranh chiếm công nghệ ở Beta.", "A fictional defense-research agency linked to Judy Reyes and competing for technology in Beta."),
        ("## Tổ chức\nDURPA là cơ quan thuộc bối cảnh Mỹ trong tác phẩm. Tên hư cấu không được dùng làm bằng chứng về hoạt động của cơ quan nghiên cứu thật.\n\n## Người và lợi ích\nJudy Reyes là đầu mối được nêu trong câu chuyện. Nghiên cứu của Kurisu và công nghệ thời gian khiến DURPA đối đầu với Strategic Focus cùng các phe khác.\n\n## Anime 0\nNhững cuộc tấn công và can thiệp quanh Radio Kaikan cho thấy việc ngăn chuyến đi của nhóm lab không chỉ do một kẻ phản diện đơn lẻ. Không suy ra mọi trực thăng hoặc tay súng đều thuộc cùng một phe nếu cảnh phim chưa nhận diện.",
         "## Organization\nDURPA is an agency in the story's American setting. Its fictional name is not evidence about a real research agency's actions.\n\n## People and interests\nJudy Reyes is its named contact in the story. Kurisu's research and temporal technology place DURPA in conflict with Strategic Focus and other factions.\n\n## Anime 0\nAttacks and interventions around Radio Kaikan show that attempts to prevent the lab's departure involve more than one villain. Not every helicopter or armed operative should be assigned to the same faction without identification."),
        ["judy-reyes", "strategic-focus", "russian-time-program", "amadeus", "radio-kaikan"],
        "Steins;Gate 0: episodes 17–18, 21–23", "DURPA")
    add("russian-time-program", "organization", "shared", 2,
        ("Phe Nga · chương trình nghiên cứu thời gian", "Russian faction · time-travel research program"),
        ("Nhóm lợi ích nhà nước và quân sự trong truyện, hưởng lợi từ luận văn Nakabachi mang sang Nga.", "The story's state and military interests benefiting from the thesis Nakabachi takes toward Russia."),
        ("## Vì sao có hồ sơ\nĐây là tên tổng hợp để tra cứu phe Nga trong anime, không phải tên chính thức của một tổ chức mới. Không tự gán FSB, SVR hay một sơ đồ chỉ huy ngoài những gì cảnh phim nêu.\n\n## Nguồn công nghệ\nNakabachi lấy luận văn của Kurisu và hướng tới Nga. Việc tri thức đó tồn tại góp phần mở cuộc đua phát triển máy thời gian ở Beta; tin tức về thí nghiệm và hoạt động tranh giành là dấu vết của cuộc đua.\n\n## Kết nối\nStrategic Focus và DURPA theo đuổi ưu thế riêng. Operation Skuld cần xử lý việc luận văn đến được nơi này, thay vì chỉ thay cảnh Kurisu bị sát hại. Tất cả là vai trò hư cấu trong tác phẩm.",
         "## Why this record exists\nThis is a lookup umbrella for the anime's Russian faction, not an invented official organization name. FSB, SVR or a detailed command structure is not assigned beyond what the adaptation identifies.\n\n## Technology source\nNakabachi takes Kurisu's thesis and heads toward Russia. Its survival helps initiate Beta's time-machine race; experimental news and competing operations are traces of that race.\n\n## Connections\nStrategic Focus and DURPA pursue their own advantages. Operation Skuld must address the thesis reaching its destination rather than only changing the scene of Kurisu's apparent death. These are fictional story roles."),
        ["doctor-nakabachi", "makise-kurisu", "beta-field", "operation-skuld", "strategic-focus", "durpa"],
        "Steins;Gate: episodes 23–24; Steins;Gate 0: episodes 4, 17–23", "World_War_III")
    add("mayqueen-nyan2", "organization", "shared", 0,
        ("MayQueen+Nyan² · maid café", "MayQueen+Nyan² · maid café"),
        ("Cơ sở kinh doanh gắn với Faris và nơi Mayuri làm thêm, một điểm gặp của nhóm ở Akihabara.", "Faris's business and Mayuri's workplace, a meeting point for the Akihabara group."),
        ("## Loại đơn vị\nMayQueen+Nyan² là maid café, được xếp trong mục tổ chức để người đọc tìm cả cơ sở kinh doanh liên quan cốt truyện. Đây không phải cơ quan nghiên cứu hoặc phe quân sự.\n\n## Con người\nFaris là gương mặt chủ chốt của quán; Mayuri làm thêm tại đây và Daru thường ghé. Văn hóa biểu diễn, cosplay và trò chơi giúp kết nối các nhóm bạn.\n\n## Theo dõi câu chuyện\nDiện mạo Akihabara và sự hiện diện của maid café có ý nghĩa khi lịch sử thay đổi. Chi tiết có spoiler được để ở hồ sơ Faris và D-mail.",
         "## Type\nMayQueen+Nyan² is a maid café, included under organizations so story-relevant businesses are searchable too. It is not a research institution or military faction.\n\n## People\nFaris is central to the café; Mayuri works there and Daru visits. Performance, cosplay and games connect the social circles.\n\n## Following the story\nAkihabara's appearance and the presence of maid cafés matter when history changes. Spoiler details are in Faris's and D-mail's records."),
        ["akiha-rumiho", "mayuri-shiina", "hashida-itaru", "akihabara"],
        "Steins;Gate: episodes 2–4, 9, 17; Steins;Gate 0: everyday setting", "May_Queen_Nyan-nyan")
    add("braun-tube-workshop", "organization", "shared", 0,
        ("Braun Tube Workshop · tiệm Mr. Braun", "Braun Tube Workshop · Mr. Braun's shop"),
        ("Tiệm TV của Yugo ở tầng dưới Future Gadget Lab, nơi Suzuha làm thêm.", "Yugo's TV shop beneath Future Gadget Lab, where Suzuha works part-time."),
        ("## Cơ sở kinh doanh\nYugo Tennouji điều hành cửa hàng chuyên TV đèn hình. Phòng lab thuê tầng trên; tiếng ồn và tiền thuê tạo ra nhiều va chạm đời thường.\n\n## Người liên quan\nNae sống cùng cha; Suzuha làm thêm ở đây. Cửa hàng tạo điểm tiếp xúc giữa gia đình Tennouji và nhóm lab.\n\n## Tách danh tính\nMột địa chỉ kinh doanh không tự chứng minh mọi người ở đó có cùng công việc bí mật. Các tiết lộ về FB và quan hệ với Rounders nằm ở hồ sơ Yugo có spoiler.",
         "## Business\nYugo Tennouji runs a cathode-ray-tube TV shop. The lab rents the room above; noise and rent produce everyday friction.\n\n## People\nNae lives with her father and Suzuha works here. The shop connects the Tennouji household with the lab.\n\n## Separate identities\nSharing a business address does not establish a shared secret occupation. Revelations about FB and the Rounders are in Yugo's spoiler-marked record."),
        ["tennouji-yugo", "tennouji-nae", "amane-suzuha", "future-gadget-lab"],
        "Steins;Gate: episodes 1–3; Steins;Gate 0: episodes 6–7", "Braun_Tube_Workshop")
    add("viral-attackers", "organization", "sg", 1,
        ("Viral Attackers", "Viral Attackers"),
        ("Nhóm đối thủ cục bộ gắn với 4℃ và tuyến RaiNet của Faris, được anime rút gọn mạnh.", "A local opponent group associated with 4℃ and Faris's RaiNet strand, heavily abridged in the anime."),
        ("## Vai trò\nViral Attackers là nhóm gắn với 4℃ trong tuyến đối đầu liên quan Faris. Đây là nhóm địa phương, không phải tổ chức đứng sau toàn bộ thí nghiệm thời gian.\n\n## Mức chuyển thể\nAnime tập 17 giữ phần rất ngắn của tuyến này, với 4℃ chỉ có giọng nói. Các cảnh gian lận giải đấu và đánh đuổi được kể dài hơn trong VN không được sao chép thành sự kiện anime ở đây.\n\n## Phân biệt\nKhông có cơ sở để xếp nhóm này làm một nhánh của SERN, Rounders, Strategic Focus hoặc DURPA.",
         "## Role\nThe Viral Attackers are associated with 4℃ in Faris's opponent storyline. They are a local group, not the force behind all time-travel experiments.\n\n## Adaptation scope\nAnime episode 17 retains only a small part of this strand, with 4℃ heard but not seen. Longer VN competition-cheating and pursuit sequences are not copied into this anime record.\n\n## Distinction\nThere is no basis here to make the group a branch of SERN, the Rounders, Strategic Focus or DURPA."),
        ["shido-4c", "akiha-rumiho", "akiha-yukitaka"], "Steins;Gate: episode 17; abbreviated RaiNet strand", "4%E2%84%83")
    add("john-titor", "concept", "shared", 2,
        ("John Titor · bí danh và lời nhắn", "John Titor · alias and messages"),
        ("Danh tính liên lạc của người du hành trong truyện; không đếm thêm một nhân vật ngoài Suzuha.", "A story time traveler's communications identity, not an extra person counted alongside Suzuha."),
        ("## Trong câu chuyện\nNhững lời nhắn của John Titor đặt câu hỏi về du hành thời gian và IBN 5100. Ở Alpha, Suzuha nhận mình dùng bí danh này. Lịch sử xuất hiện và nội dung lời nhắn phụ thuộc world line.\n\n## Tránh đếm trùng\nSuzuha, John Titor và Hashida Suzu là các danh tính liên quan tới cùng tuyến người du hành, không phải ba lab mem. Barrel Titor là bí danh gắn với Daru ở tương lai, cần phân biệt.\n\n## Ngoài tác phẩm\nTác phẩm mượn tên từ truyền thuyết Internet; hồ sơ chỉ mô tả vai trò hư cấu, không xác nhận câu chuyện du hành thời gian ngoài đời.",
         "## Within the story\nJohn Titor's messages raise questions about time travel and the IBN 5100. In Alpha, Suzuha identifies herself as the alias's user. The messages' appearance and content depend on the world line.\n\n## Avoid double counting\nSuzuha, John Titor and Hashida Suzu are identities associated with the same traveler strand, not three lab members. Barrel Titor is associated with future Daru and must be distinguished.\n\n## Outside the work\nThe work borrows a name from Internet lore. This record describes a fictional role, not evidence of real time travel."),
        ["amane-suzuha", "hashida-itaru", "doctor-nakabachi", "sern"],
        "Steins;Gate: episodes 1, 3–4, 14–16; Steins;Gate 0: future context", "John_Titor")

    journeys = [
        ("kurisu-journey", "Makise Kurisu · hành trình Alpha / Beta", "Makise Kurisu · Alpha / Beta journey", "makise-kurisu",
         "Kurisu thật, sự hy sinh ở Alpha và di sản ký ức trong Beta.", "The living Kurisu, her Alpha sacrifice and memory legacy in Beta.",
         "## Alpha\nKurisu từ người hoài nghi trở thành cộng sự then chốt trong việc phát triển time leap. Cô giúp Okabe giữ lý trí sau nhiều thất bại cứu Mayuri. Khi biết trở về Beta sẽ khiến mình chết, cô vẫn chấp nhận để Mayuri có cơ hội sống; quan hệ giữa cô và Okabe vượt khỏi những cuộc tranh luận ban đầu.\n\n## Beta\nCô gặp cha ở Radio Kaikan; luận văn bị lấy và dẫn tới cuộc đua công nghệ. Operation Skuld thay kết quả mà giữ điều Okabe lúc đầu tưởng đã nhìn thấy.\n\n## Amadeus và 0\nBản ký ức là một thực thể có mốc ghi nhận riêng, không sở hữu tự động ký ức ở lab Alpha. Laptop, nghiên cứu và dữ liệu ký ức làm di sản của cô trở thành mục tiêu. Xóa dữ liệu Amadeus là một tổn thất trong con đường thay đổi tương lai, không phải bằng chứng Kurisu chưa từng tồn tại.",
         "## Alpha\nKurisu moves from skepticism to a central role in developing time leap. She helps Okabe remain rational after repeated failures to save Mayuri. Knowing a return to Beta means her own death, she still accepts Mayuri's chance to live; her bond with Okabe grows beyond their initial arguments.\n\n## Beta\nShe confronts her father at Radio Kaikan; her stolen thesis enables the technology race. Operation Skuld changes the outcome while preserving what the first Okabe believes he saw.\n\n## Amadeus and 0\nThe memory system has its own snapshot boundary and does not automatically remember Alpha's lab life. Her laptop, research and memory data become targets. Erasing Amadeus data is a loss along the path to changing the future, not proof Kurisu never existed.",
         ["doctor-nakabachi", "amadeus", "hiyajo-maho", "operation-skuld", "alpha-field", "beta-field"],
         "Steins;Gate: episodes 11–14, 21–24; Steins;Gate 0: episodes 1–3, 8, 22–23", "Kurisu_Makise"),
        ("okabe-journey", "Okabe · từ Kyouma đến Operation Skuld", "Okabe · from Kyouma to Operation Skuld", "okabe-rintaro",
         "Reading Steiner, chấn thương qua các lần cứu thất bại và quyết định trao cơ hội cho bản thân quá khứ.", "Reading Steiner, trauma from failed rescues and the decision to give his past self another chance.",
         "## Alpha\nOkabe giữ ký ức khi lịch sử tái cấu trúc. Các D-mail của nhóm dẫn tới việc mất IBN 5100; anh phải hủy từng thay đổi, rồi xóa bản ghi D-mail đầu tiên khỏi hệ thống SERN. Cứu Mayuri buộc anh đối mặt cái chết của Kurisu ở Beta.\n\n## Ngã rẽ 23β\nSau lần cứu Kurisu thất bại, anh từ bỏ vai Kyouma. Đây là điểm xuất phát của 0; không ghép nó với quyết định thử lại ngay ở tập 23 gốc như hai sự kiện liên tiếp của một lịch sử duy nhất.\n\n## 0 và thông điệp tương lai\nGặp Amadeus khơi lại mất mát. Tương lai 2036 và sự giúp đỡ của đồng đội khiến anh trở lại hành động, thực hiện hàng nghìn time leap và chuẩn bị thông điệp Operation Skuld. Anh tạo điều kiện cho một Okabe khác thành công, không mặc nhiên chuyển mọi ký ức Beta sang người ở đích Steins Gate.",
         "## Alpha\nOkabe retains memories when history restructures. The lab's D-mails lead to losing the IBN 5100; he reverses the changes and deletes the first D-mail's SERN record. Saving Mayuri forces him to confront Kurisu's death in Beta.\n\n## The 23β branch\nAfter his failed Kurisu rescue, he abandons Kyouma. This starts 0; it should not be joined to the original episode 23's immediate retry as consecutive events in one unchanged history.\n\n## 0 and the future message\nAmadeus revives his grief. The 2036 future and his friends' support bring him back into action, through thousands of time leaps and preparations for Operation Skuld's message. He enables another Okabe to succeed rather than automatically giving the destination's Okabe every Beta memory.",
         ["reading-steiner", "mayuri-shiina", "amadeus", "amane-suzuha", "valkyrie", "operation-skuld"],
         "Steins;Gate: episodes 12–24 and alternate 23β; Steins;Gate 0: episodes 1, 19–23", "Rintaro_Okabe/Plot"),
        ("mayuri-journey", "Mayuri · hội tụ và lời thúc giục quá khứ", "Mayuri · convergence and encouragement to the past", "mayuri-shiina",
         "Từ người được cứu trong Alpha tới lựa chọn chủ động giúp Okabe thử lại ở 0.", "From the person being saved in Alpha to actively helping Okabe try again in 0.",
         "## Trước thí nghiệm\nMất bà khiến Mayuri rơi vào buồn bã; vai diễn Kyouma là một cách Okabe giữ bạn ở lại với đời sống. Sự quan tâm của cô thường xuất hiện qua những quan sát rất nhỏ.\n\n## Alpha\nCái chết của cô trở thành điểm hội tụ mà việc đổi một hành động không đủ phá vỡ. Đảo chuỗi D-mail và xóa dấu vết khiến SERN chú ý giúp chuyển sang Beta, nơi Mayuri sống nhưng Kurisu chết.\n\n## Beta và 0\nTrong tương lai cô nhận nuôi Kagari. Ở hiện tại cô nhận ra mình đã góp phần để Okabe từ bỏ sau lần cứu thất bại, rồi quyết định đi cùng Suzuha để thúc giục Mayuri quá khứ giúp anh đứng dậy. Mayuri không chỉ là mục tiêu được bảo vệ; quyết định của cô là một điều kiện cho lần thử lại.",
         "## Before the experiments\nLosing her grandmother leaves Mayuri grieving; Kyouma is one way Okabe keeps his friend connected to life. Her care often appears through small observations.\n\n## Alpha\nHer death becomes a convergence that changing one action cannot overcome. Reversing the D-mails and removing the trace attracting SERN enables a return to Beta, where Mayuri lives but Kurisu dies.\n\n## Beta and 0\nShe adopts Kagari in the future. In the present she recognizes her part in Okabe giving up after his failed rescue, then chooses to travel with Suzuha and encourage her past self to help him rise again. She is more than someone to protect: her decision helps enable another attempt.",
         ["mayuri-grandmother", "okabe-rintaro", "shiina-kagari", "amane-suzuha", "alpha-field", "operation-skuld"],
         "Steins;Gate: episodes 12–13, 21–23 and 23β; Steins;Gate 0: episodes 12, 16–18, 21–23", "Mayuri_Shiina"),
        ("daru-journey", "Daru · kỹ thuật, gia đình và kháng chiến", "Daru · engineering, family and resistance", "hashida-itaru",
         "Người biến lý thuyết thành thiết bị, cha của Suzuha và điểm tựa kỹ thuật qua tương lai chiến tranh.", "The engineer turning theory into equipment, Suzuha's father and a technical anchor through the wartime future.",
         "## Năng lực\nDaru xử lý máy tính, khảo sát dữ liệu SERN và triển khai thiết bị của lab. Ý tưởng của Kurisu cần công việc kỹ thuật của anh để thành một hệ thống sử dụng được.\n\n## Gia đình\nAnh là cha tương lai của Suzuha; Yuki là mẹ cô. Cuộc gặp cha con ở Alpha và những buổi hẹn ở 0 đặt anh vào vai người xây dựng tương lai bằng cả kỹ thuật lẫn chăm sóc người khác. Barrel Titor là bí danh gắn với anh ở tương lai.\n\n## Beta\nDaru cùng Maho phát triển lại time leap và duy trì công việc của lực lượng kháng chiến. Anh hỗ trợ những điều kiện kỹ thuật để thông điệp tương lai và chuyến đi của Suzuha có thể diễn ra. Không coi mọi đời máy thời gian của anh là một thiết bị giống hệt nhau.",
         "## Skills\nDaru handles computing, investigates SERN data and implements the lab's equipment. Kurisu's ideas require his engineering work to become a usable system.\n\n## Family\nHe is Suzuha's future father, with Yuki as her mother. Alpha's father-daughter meeting and 0's dates make him someone building the future through both engineering and care. Barrel Titor is associated with his future identity.\n\n## Beta\nDaru and Maho redevelop time leap and sustain resistance work. He supports the technical conditions for the future message and Suzuha's journey. His different time-machine models should not be treated as identical equipment.",
         ["amane-suzuha", "amane-yuki", "hiyajo-maho", "valkyrie", "phonewave", "john-titor"],
         "Steins;Gate: episodes 4–5, 11, 15–16; Steins;Gate 0: episodes 14–15, 19–23", "Itaru_Hashida"),
        ("maho-journey", "Maho · vượt chiếc bóng của Kurisu", "Maho · beyond Kurisu's shadow", "hiyajo-maho",
         "Tình bạn, sự tự so sánh và quyết định tiếp tục nghiên cứu dù biết cái giá của nó.", "Friendship, self-comparison and the choice to continue researching despite its cost.",
         "## Ký ức về Kurisu\nMaho ngưỡng mộ nhưng cũng tự ti trước thành tích của Kurisu. Cô biết Amadeus là hệ thống ký ức, vì vậy nhắc Okabe phân biệt sự hiện diện qua màn hình với việc người đã mất sống lại.\n\n## Nghiên cứu và nguy hiểm\nLaptop của Kurisu cùng dữ liệu Amadeus kéo cô vào cuộc tranh giành. Là cộng sự của Leskinen không đồng nghĩa cô biết trước kế hoạch của ông. Sự giúp đỡ của Faris và tình bạn với những người ở lab tạo chỗ dựa mới cho cô.\n\n## Lựa chọn của chính mình\nMaho hợp tác với Daru phát triển time leap, hỗ trợ những nỗ lực trở về từ tương lai và xử lý dữ liệu Amadeus. Vai trò của cô không dừng ở người thay Kurisu; cô có đóng góp, tình cảm và quyết định riêng.",
         "## Remembering Kurisu\nMaho admires Kurisu while feeling overshadowed by her achievements. Knowing Amadeus is a memory system, she asks Okabe to distinguish screen-mediated presence from the dead returning to life.\n\n## Research and danger\nKurisu's laptop and Amadeus data pull her into the technology struggle. Working with Leskinen does not mean she knew his plans. Faris's help and friendships around the lab give her new support.\n\n## Her own choices\nMaho works with Daru to develop time leap, supports attempts to return from the future and helps address Amadeus data. Her role is not merely replacing Kurisu: she has contributions, attachments and decisions of her own.",
         ["makise-kurisu", "hashida-itaru", "akiha-rumiho", "alexis-leskinen", "amadeus", "valkyrie"],
         "Steins;Gate 0: episodes 1–3, 9–11, 14, 19–23", "Maho_Hiyajo"),
    ]
